// sync_fifo_tb: self-checking testbench for sync_fifo.
// Two FIFOs (DEPTH 8 x WIDTH 8, DEPTH 5 x WIDTH 12) on the same stimulus,
// each checked every cycle against a reference queue.
`timescale 1ns/1ps

module sync_fifo_tb;

    localparam integer D_A  = 8;
    localparam integer W_A  = 8;
    localparam integer D_B  = 5;
    localparam integer W_B  = 12;
    localparam integer CW_A = $clog2(D_A + 1);
    localparam integer CW_B = $clog2(D_B + 1);
    localparam integer NCOV = 9;
    localparam [W_B-1:0] MASK_A = {{(W_B-W_A){1'b0}}, {W_A{1'b1}}};

    reg            clk     = 1'b0;
    reg            rst_n   = 1'b0;
    reg            wr_en   = 1'b0;
    reg            rd_en   = 1'b0;
    reg  [W_B-1:0] wr_data = {W_B{1'b0}};

    wire            full_a, empty_a;
    wire [W_A-1:0]  rd_data_a;
    wire [CW_A-1:0] count_a;
    wire            full_b, empty_b;
    wire [W_B-1:0]  rd_data_b;
    wire [CW_B-1:0] count_b;

    sync_fifo #(.DEPTH(D_A), .WIDTH(W_A)) dut_a (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data[W_A-1:0]), .full(full_a),
        .rd_en(rd_en), .rd_data(rd_data_a), .empty(empty_a),
        .count(count_a)
    );

    sync_fifo #(.DEPTH(D_B), .WIDTH(W_B)) dut_b (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data), .full(full_b),
        .rd_en(rd_en), .rd_data(rd_data_b), .empty(empty_b),
        .count(count_b)
    );

    always #5 clk = ~clk;

    // Reference queues: fifo f uses q[f*8 .. f*8+depth-1].
    reg [W_B-1:0] q [0:15];
    integer head   [0:1];
    integer cnt    [0:1];
    integer pushes [0:1];
    integer pops   [0:1];
    integer cov    [0:2*NCOV-1];
    reg     model_valid;

    integer passed;
    integer failed;
    integer cyc;
    integer i;
    integer k;
    integer f;
    integer seg;
    integer pw;
    integer pr;
    reg [31:0]      seed;
    reg [8*64-1:0]  nonce;

    function [31:0] xs;
        input [31:0] x;
        reg   [31:0] y;
        begin
            y  = x ^ (x << 13);
            y  = y ^ (y >> 17);
            y  = y ^ (y << 5);
            xs = y;
        end
    endfunction

    function integer depth_of;
        input integer ff;
        begin
            depth_of = (ff == 0) ? D_A : D_B;
        end
    endfunction

    task check_fifo;
        input integer ff;
        integer       dep;
        integer       act_cnt;
        reg           act_full;
        reg           act_empty;
        reg [W_B-1:0] act_data;
        reg [W_B-1:0] exp_data;
        begin
            dep = depth_of(ff);
            if (ff == 0) begin
                act_cnt   = count_a;
                act_full  = full_a;
                act_empty = empty_a;
                act_data  = {{(W_B-W_A){1'b0}}, rd_data_a};
            end else begin
                act_cnt   = count_b;
                act_full  = full_b;
                act_empty = empty_b;
                act_data  = rd_data_b;
            end

            if (act_cnt !== cnt[ff]) begin
                $error("fifo %0d cycle %0d: count %0d, expected %0d", ff, cyc, act_cnt, cnt[ff]);
                failed = failed + 1;
            end else begin
                passed = passed + 1;
            end

            if (act_full !== (cnt[ff] == dep)) begin
                $error("fifo %0d cycle %0d: full %b, expected %b", ff, cyc, act_full, (cnt[ff] == dep));
                failed = failed + 1;
            end else begin
                passed = passed + 1;
            end

            if (act_empty !== (cnt[ff] == 0)) begin
                $error("fifo %0d cycle %0d: empty %b, expected %b", ff, cyc, act_empty, (cnt[ff] == 0));
                failed = failed + 1;
            end else begin
                passed = passed + 1;
            end

            if (cnt[ff] != 0) begin
                exp_data = q[ff*8 + head[ff]];
                if (act_data !== exp_data) begin
                    $error("fifo %0d cycle %0d: rd_data %h, expected %h", ff, cyc, act_data, exp_data);
                    failed = failed + 1;
                end else begin
                    passed = passed + 1;
                end
            end
        end
    endtask

    // Model update for the rising edge just taken, using the inputs held
    // across it and the model state from before it.
    task model_step;
        input integer ff;
        integer dep;
        integer w_acc;
        integer r_acc;
        integer pos;
        begin
            dep = depth_of(ff);
            if (!rst_n) begin
                if (model_valid && (cnt[ff] > 0)) begin
                    cov[ff*NCOV + 8] = cov[ff*NCOV + 8] + 1;
                end
                cnt[ff]  = 0;
                head[ff] = 0;
            end else if (model_valid) begin
                w_acc = (wr_en && (cnt[ff] != dep)) ? 1 : 0;
                r_acc = (rd_en && (cnt[ff] != 0)) ? 1 : 0;

                if (cnt[ff] == dep)                                 cov[ff*NCOV + 0] = cov[ff*NCOV + 0] + 1;
                if (wr_en && (cnt[ff] == dep))                      cov[ff*NCOV + 1] = cov[ff*NCOV + 1] + 1;
                if ((r_acc == 1) && (w_acc == 0) && (cnt[ff] == 1)) cov[ff*NCOV + 2] = cov[ff*NCOV + 2] + 1;
                if (rd_en && (cnt[ff] == 0))                        cov[ff*NCOV + 3] = cov[ff*NCOV + 3] + 1;
                if (wr_en && rd_en && (cnt[ff] == 0))               cov[ff*NCOV + 4] = cov[ff*NCOV + 4] + 1;
                if (wr_en && rd_en && (cnt[ff] == dep))             cov[ff*NCOV + 5] = cov[ff*NCOV + 5] + 1;
                if (wr_en && rd_en && (cnt[ff] > 0) && (cnt[ff] < dep))
                                                                    cov[ff*NCOV + 6] = cov[ff*NCOV + 6] + 1;

                pos = (head[ff] + cnt[ff]) % dep;
                if (w_acc == 1) begin
                    if (ff == 0) q[ff*8 + pos] = wr_data & MASK_A;
                    else         q[ff*8 + pos] = wr_data;
                    pushes[ff] = pushes[ff] + 1;
                end
                if (r_acc == 1) begin
                    head[ff] = (head[ff] + 1) % dep;
                    pops[ff] = pops[ff] + 1;
                end
                cnt[ff] = cnt[ff] + w_acc - r_acc;
            end
        end
    endtask

    // One clock cycle: check the state at the falling edge, drive the
    // inputs, then update the models after the rising edge.
    task do_cycle;
        input           r_n;
        input           w;
        input           r;
        input [W_B-1:0] d;
        begin
            @(negedge clk);
            if (model_valid) begin
                check_fifo(0);
                check_fifo(1);
            end
            rst_n   = r_n;
            wr_en   = w;
            rd_en   = r;
            wr_data = d;
            @(posedge clk);
            model_step(0);
            model_step(1);
            if (!r_n) model_valid = 1'b1;
            cyc = cyc + 1;
        end
    endtask

    task next_rand;
        begin
            seed = xs(seed);
        end
    endtask

    initial begin
        passed      = 0;
        failed      = 0;
        cyc         = 0;
        model_valid = 1'b0;
        seed        = 32'h1234_5678;
        for (f = 0; f < 2; f = f + 1) begin
            head[f]   = 0;
            cnt[f]    = 0;
            pushes[f] = 0;
            pops[f]   = 0;
        end
        for (k = 0; k < 2*NCOV; k = k + 1) cov[k] = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = "none";
        end

        // Reset, with requests during reset (they must be ignored).
        for (i = 0; i < 3; i = i + 1) do_cycle(1'b0, 1'b1, 1'b1, 12'hA5A);

        // Read while empty.
        for (i = 0; i < 2; i = i + 1) do_cycle(1'b1, 1'b0, 1'b1, 12'h000);

        // Write and read together when empty: only the write is accepted.
        do_cycle(1'b1, 1'b1, 1'b1, 12'h3C1);

        // Fill to full, then keep writing (write while full is dropped).
        for (i = 0; i < 10; i = i + 1) do_cycle(1'b1, 1'b1, 1'b0, 12'h100 + i);

        // Write and read together when full, then in between.
        for (i = 0; i < 3; i = i + 1) do_cycle(1'b1, 1'b1, 1'b1, 12'h200 + i);

        // Drain to empty, then keep reading (read while empty is ignored).
        for (i = 0; i < 12; i = i + 1) do_cycle(1'b1, 1'b0, 1'b1, 12'h000);

        // Reset during traffic.
        for (i = 0; i < 3; i = i + 1) do_cycle(1'b1, 1'b1, 1'b0, 12'h300 + i);
        for (i = 0; i < 2; i = i + 1) do_cycle(1'b0, 1'b1, 1'b1, 12'h3F0 + i);

        // Biased random traffic with rare resets.
        for (seg = 0; seg < 8; seg = seg + 1) begin
            case (seg)
                0:       begin pw = 200; pr = 60;  end
                1:       begin pw = 60;  pr = 200; end
                2:       begin pw = 128; pr = 128; end
                3:       begin pw = 240; pr = 240; end
                4:       begin pw = 230; pr = 30;  end
                5:       begin pw = 30;  pr = 230; end
                6:       begin pw = 160; pr = 150; end
                default: begin pw = 255; pr = 255; end
            endcase
            for (i = 0; i < 300; i = i + 1) begin
                next_rand;
                do_cycle((seed[30:22] != 9'd0),
                         (seed[7:0]  < pw),
                         (seed[15:8] < pr),
                         seed[31:20]);
            end
        end

        // Final drain, then one idle cycle so the last state is checked.
        for (i = 0; i < 10; i = i + 1) do_cycle(1'b1, 1'b0, 1'b1, 12'h000);
        do_cycle(1'b1, 1'b0, 1'b0, 12'h000);

        // Coverage: every corner case in the interface spec must be reached.
        for (f = 0; f < 2; f = f + 1) begin
            if (pops[f] > depth_of(f)) cov[f*NCOV + 7] = 1;
            for (k = 0; k < NCOV; k = k + 1) begin
                if (cov[f*NCOV + k] == 0) begin
                    $error("fifo %0d: coverage point %0d not reached", f, k);
                    failed = failed + 1;
                end else begin
                    passed = passed + 1;
                end
            end
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
